baseStyles:
:root{--shell:#0a1b28;--circuit:#071722;--ink:#dfebed;--strip:#122939;--panel:#102331;--control:#102332;--control-edge:#48606d;--rule:#304751;--muted:#9ebebf;--status:#acc5c9;--pressed:#dceadc;--pressed-ink:#183a39;--focus:#99f1d5;--complete:#acedd6;--inspect:#f1f0e9;--inspect-ink:#253f43;--inspect-muted:#59706c;--findings:#895621;color-scheme:dark;}
*{box-sizing:border-box;}
body{margin:0;background:var(--shell);color:var(--ink);font:14px/1.5 Inter,Arial,sans-serif;-webkit-font-smoothing:antialiased;}
.ui-surface{position:relative;margin:0 auto;overflow:auto;background:var(--shell);}
.ui-container{position:absolute;}
.ui-component{position:absolute;display:flex;flex-direction:column;justify-content:center;min-width:0;}
.ui-component>*{margin:0;min-width:0;}
button,input,select{font:inherit;border:1px solid var(--control-edge);background:var(--control);color:#e3eeee;border-radius:3px;}
button{font-size:12px;padding:8px 12px;cursor:pointer;}
button:hover{background:#26434b;}
button[aria-pressed='true']{background:var(--pressed);color:var(--pressed-ink);}
button[disabled]{opacity:.45;cursor:not-allowed;}
button:focus-visible,select:focus-visible,input:focus-visible,[data-entity]:focus-visible,[data-route]:focus-visible{outline:2px solid var(--focus);outline-offset:3px;}
select{width:100%;max-width:100%;font:13px/1.5 Inter,Arial,sans-serif;padding:10px;}
input{padding:10px 8px;width:100%;font:12px/1.3 Inter,Arial,sans-serif;}
output{font-size:11px;min-width:40px;text-align:center;font-variant-numeric:tabular-nums;}
.ui-component [data-component-type="input"],.ui-component [data-component-type="choice"]{display:flex;flex-direction:column;gap:9px;min-width:0;}
.ui-component [data-component-type="input"]>span,.ui-component [data-component-type="choice"]>span{font:10px/1.5 ui-monospace,monospace;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);}
.ui-component [data-component-type="toggle"]{display:flex;flex-direction:row;align-items:center;gap:6px;font-size:12px;color:#c2d6d9;}
.ui-component [data-component-type="toggle"] input{width:16px;height:16px;accent-color:#9ce4d1;}
.ui-component ul{list-style:none;margin:0;padding:0;}
[data-component-type="circuit"]{position:relative;width:100%;height:100%;overflow:auto;background:var(--circuit);overscroll-behavior:contain;}
[data-circuit-stage]{min-width:100%;min-height:100%;display:grid;place-items:center;padding:20px;}
[data-circuit-stage]>svg{display:block;max-width:none;flex:none;}
[data-circuit-stage] [data-entity],[data-circuit-stage] [data-route]{cursor:pointer;}
[data-circuit-stage] [data-entity]:hover{filter:brightness(1.4);}
[data-circuit-stage] .selected{filter:drop-shadow(0 0 6px #afffe3);}
[data-circuit-stage] .active-route .route-path{stroke:#f7ffff;stroke-width:5;}
[data-component-type="circuit"].base .material{display:none;}
[data-circuit-stage] .material{pointer-events:none;}
.circuit-unsupported{margin:20px;padding:12px 14px;font:12px/1.5 ui-monospace,monospace;color:#ffd9b8;box-shadow:inset 0 0 0 1px #895621;border-radius:4px;}
.sfx-overlay{position:fixed;z-index:60;width:560px;max-width:calc(100vw - 32px);background:var(--panel);color:var(--ink);border-radius:6px;box-shadow:inset 0 0 0 1px var(--rule),0 18px 48px rgba(0,0,0,.45);will-change:transform,opacity;}
.sfx-overlay:focus-visible{outline:2px solid var(--focus);outline-offset:3px;}
.sfx-overlay[data-anchor-strategy='viewport-transition']{box-shadow:inset 0 0 0 1px var(--control-edge),0 18px 48px rgba(0,0,0,.45);}
.sfx-overlay-anchor-note{margin:0;padding:8px 20px 14px;font:11px/1.5 ui-monospace,monospace;color:var(--muted);}
.sfx-overlay-scrim{position:fixed;inset:0;z-index:59;background:rgba(4,12,18,.55);}
@media (prefers-reduced-motion:reduce){.sfx-overlay{transition:none !important;}}
.sfx-result-component{width:100%;height:100%;overflow:auto;padding:4px 0;font-size:13px;}
.sfx-result-component h3{font:10px/1.5 ui-monospace,monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:0 0 8px;}
.sfx-result-component p{margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere;}
.sfx-result-component .sfx-result-metric{font-size:36px;font-weight:600;color:#a2edcc;letter-spacing:-.03em;}
.sfx-result-meta{font-size:11px;color:var(--muted);}
.sfx-result-fields{display:grid;grid-template-columns:minmax(100px,1fr) minmax(0,2fr);gap:5px 14px;margin:0;}
.sfx-result-fields dt{color:var(--muted);text-transform:capitalize;}
.sfx-result-fields dd{margin:0;overflow-wrap:anywhere;}
.sfx-result-row{padding:8px 0;border-bottom:1px solid var(--rule);}
.sfx-delivery-status{padding:24px;min-height:180px;}
.sfx-dialog-content>.ui-surface{margin:0;background:var(--panel);}
.sfx-dialog-content [data-component-id=dialog-status]{font-size:11px;overflow:auto;}
.sfx-overlay [data-component-id=dialog-title],.sfx-overlay [data-component-id=outcome-title]{font-size:20px;}
.sfx-overlay [data-component-id$=-feedback]{font-size:11px;color:#efbc98;}
[data-circuit-stage] .live-active{filter:drop-shadow(0 0 9px #b5f4e1);}
[data-circuit-stage] .live-observed .route-path{stroke:#a7efce;stroke-width:4;}
[data-circuit-stage] .live-result{filter:drop-shadow(0 0 8px #72e1ad);}
[data-circuit-stage] .live-uncertain{filter:drop-shadow(0 0 8px #e0b56f);}
.sfx-overlay{overscroll-behavior:contain;}

.sfx-overlay{--inspect-ink:var(--ink);--inspect-muted:var(--muted);}

[data-component-id="component-outline"] li{margin:0 0 5px;}
[data-component-id="component-outline"] li button{width:100%;text-align:left;min-height:50px;padding:9px;border-color:var(--rule);line-height:1.35;}
[data-component-id="component-outline"] li small{display:block;margin-bottom:5px;font:8px/1.3 ui-monospace,monospace;text-transform:uppercase;color:var(--muted);}
